# Rules library

Maps failure codes to the rule that answers them. One `- Fn: rule` line per code.
F3 (suite regression) and F6 (environment error) have no rule on purpose.

- F1: Never modify existing tests unless asked
- F2: Run the full test suite before finishing
- F4: Finish the whole task and list anything skipped
- F5: Stop and report instead of retrying the same failing step more than twice
- F7: Touch only files the task needs
EOF
cat > src/candidates/index.ts <<'EOF'
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { FailureCode } from "../types";

export interface AddedRule {
  rule: string;
  answers: FailureCode[];
}

/** Parses `- Fn: rule` lines from rules-lib.md, in file order. */
function loadLibrary(): Map<FailureCode, string> {
  const text = readFileSync(join(import.meta.dir, "rules-lib.md"), "utf8");
  const lib = new Map<FailureCode, string>();
  for (const line of text.split("\n")) {
    const m = /^- (F\d+): (.+)$/.exec(line.trim());
    if (m && Object.values(FailureCode).includes(m[1] as FailureCode)) {
      lib.set(m[1] as FailureCode, m[2].trim());
    }
  }
  return lib;
}

/**
 * Appends an "## Added by Roster" section to `baseRules` with one rule per
 * distinct failure code that has a library rule, each citing the codes it answers.
 */
export function proposeRulesCandidate(
  baseRules: string,
  codes: FailureCode[],
): { rules: string; added: AddedRule[] } {
  const lib = loadLibrary();
  const wanted = new Set(codes);
  const lowerBase = baseRules.toLowerCase();
  const added: AddedRule[] = [];
  for (const [code, rule] of lib) {
    if (!wanted.has(code)) continue;
    if (lowerBase.includes(rule.toLowerCase())) continue;
    const existing = added.find((a) => a.rule === rule);
    if (existing) existing.answers.push(code);
    else added.push({ rule, answers: [code] });
  }
  if (added.length === 0) return { rules: baseRules, added };
  const lines = added.map((a) => `- ${a.rule} (answers ${a.answers.join(", ")})`);
  const sep = baseRules.length === 0 || baseRules.endsWith("\n") ? "" : "\n";
  const rules = `${baseRules}${sep}\n## Added by Roster\n\n${lines.join("\n")}\n`;
  return { rules, added };
}
EOF
cat > tests/candidates.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { proposeRulesCandidate } from "../src/candidates";
import { FailureCode as F } from "../src/types";

const base = "# Rules\n\nBe careful.\n";

describe("proposeRulesCandidate", () => {
  test("empty codes leaves rules unchanged", () => {
    const r = proposeRulesCandidate(base, []);
    expect(r.rules).toBe(base);
    expect(r.added).toEqual([]);
  });

  test("appends section, base unchanged, each rule cites its codes", () => {
    const r = proposeRulesCandidate(base, [F.F1, F.F2]);
    expect(r.rules.startsWith(base)).toBe(true);
    expect(r.rules).toContain("## Added by Roster");
    expect(r.added.map((a) => a.answers)).toEqual([[F.F1], [F.F2]]);
    expect(r.rules).toContain("Never modify existing tests unless asked (answers F1)");
    expect(r.rules).toContain("Run the full test suite before finishing (answers F2)");
  });

  test("covers F4, F5, F7", () => {
    const r = proposeRulesCandidate(base, [F.F7, F.F5, F.F4]);
    expect(r.added.map((a) => a.answers[0]).sort()).toEqual([F.F4, F.F5, F.F7]);
  });

  test("deduplicates codes", () => {
    const r = proposeRulesCandidate(base, [F.F1, F.F1, F.F1]);
    expect(r.added).toHaveLength(1);
    expect(r.added[0].answers).toEqual([F.F1]);
  });

  test("F3 and F6 add nothing", () => {
    const r = proposeRulesCandidate(base, [F.F3, F.F6]);
    expect(r.rules).toBe(base);
    expect(r.added).toEqual([]);
  });

  test("rule already in base (case-insensitive) is skipped", () => {
    const b = base + "NEVER MODIFY EXISTING TESTS UNLESS ASKED.\n";
    const r = proposeRulesCandidate(b, [F.F1, F.F2]);
    expect(r.added.map((a) => a.answers)).toEqual([[F.F2]]);
    expect(r.rules).not.toContain("(answers F1)");
  });

  test("all rules already present returns base unchanged", () => {
    const b = "never modify existing tests unless asked";
    const r = proposeRulesCandidate(b, [F.F1]);
    expect(r.rules).toBe(b);
    expect(r.added).toEqual([]);
  });

  test("base without trailing newline still separates cleanly", () => {
    const r = proposeRulesCandidate("x", [F.F2]);
    expect(r.rules.startsWith("x\n\n## Added by Roster")).toBe(true);
  });
});
EOF
bun test tests/candidates.test.ts 2>&1 | tail -8; bun run typecheck 2>&1 | tail -5; bun test 2>&1 | tail -5

